  "settings.game.experimentalBadge": "Experimental",
  "settings.game.cacheRollingBranchesDocTitle": "Cómo funciona el almacenamiento en caché de ramas de desarrollo y repeticiones",
  "settings.game.cacheRollingBranchesDocOverview": "Las ramas continuas como FAF Develop y FAF Beta no tienen números de versión permanentes en el servidor. Cuando se publican nuevos cambios, los archivos anteriores se sobrescriben, lo que provoca que las repeticiones antiguas se desincronicen.",
  "settings.game.cacheRollingBranchesDocHowTitle": "Instantáneas de versión",
  "settings.game.cacheRollingBranchesDocHowDesc": "Al activarse, cada compilación única se identifica con su SHA de commit de Git y hash de archivos, y se registra en un manifiesto local.",
  "settings.game.cacheRollingBranchesDocReplayTitle": "Cambios en archivos de repetición",
  "settings.game.cacheRollingBranchesDocReplayDesc": "Los archivos .fafreplay locales incluyen los campos git_sha, git_short_sha y build_signature en su encabezado JSON. Esto permite restaurar la versión exacta durante la reproducción sin perder compatibilidad con otros clientes de FAF.",
  "settings.game.cacheRollingBranchesDocStorageTitle": "Eficiencia de almacenamiento",
  "settings.game.cacheRollingBranchesDocStorageDesc": "Los archivos se vinculan mediante enlaces físicos sin duplicar espacio en disco. Puede inspeccionarlos o eliminarlos en la lista inferior.",
