  "settings.discord.disallowJoinsViaHint": "Mantener el estado visible, pero quitar el botón de unirse para que nadie entre en tu sala desde Discord.",
  "settings.steam.presence": "Estado de Steam",
  "settings.steam.presenceHint": "Mientras estás en una partida, Steam te muestra jugando a Forged Alliance y cuenta las horas; tener el cliente abierto no cuenta. Necesita Steam abierto y Forged Alliance en tu biblioteca. Desactivado salvo que lo actives.",
  "settings.steam.confirmButton": "Activar",
  "settings.steam.confirmTitle": "¿Activar el estado de Steam?",
  "settings.steam.confirmBody": "El cliente cargará la biblioteca Steamworks de Valve, de código cerrado, mientras juegas. Le dice a Steam cuándo juegas a Forged Alliance en FAF, y no podemos comprobar qué más podría enviar la biblioteca a Valve.",
  "settings.steam.trustClosed": "Para ello el cliente tiene que cargar la biblioteca Steamworks de Valve, que es de código cerrado. Elegimos qué funciones llamamos, y solo llamamos a tres (iniciar, mantener, cerrar), pero no podemos ver ni comprobar qué hace o envía a Valve la propia biblioteca. Activarlo es confiar en Valve para eso.",
  "settings.steam.trustCalls": "El cliente solo le dice a Steam que empezaste y dejaste de jugar a Forged Alliance. Steam sabe entonces qué cuenta jugó y de cuándo a cuándo, y se lo muestra a tus amigos según tu propia privacidad de Steam. FAF es un cliente aparte: sin esto, Steam no sabe cuándo juegas en FAF.",
  "settings.steam.trustTitle": "Qué envía, y qué no podemos comprobar",

